static bool hour_mask(int size, int hour, int x, int y) {
  if (x < 0 || y < 0 || x >= size || y >= size) return false;
  const uint16_t *offsets; const uint8_t *spans;
  switch (size) {
#if !defined(PBL_DISPLAY_WIDTH) || defined(PBL_PLATFORM_BASALT) || defined(PBL_PLATFORM_DIORITE) || defined(PBL_PLATFORM_FLINT)
    case 127: offsets = MASK_127_OFFSETS; spans = MASK_127_SPANS; break;
#endif
#if !defined(PBL_DISPLAY_WIDTH) || defined(PBL_PLATFORM_CHALK)
    case 158: offsets = MASK_158_OFFSETS; spans = MASK_158_SPANS; break;
#endif
#if !defined(PBL_DISPLAY_WIDTH) || defined(PBL_PLATFORM_EMERY)
    case 176: offsets = MASK_176_OFFSETS; spans = MASK_176_SPANS; break;
#endif
#if !defined(PBL_DISPLAY_WIDTH) || defined(PBL_PLATFORM_GABBRO)
    case 229: offsets = MASK_229_OFFSETS; spans = MASK_229_SPANS; break;
#endif
    default: return false;
  }
  int row = (hour - 1) * (size + 1) + y;
  for (int i = offsets[row]; i < offsets[row + 1]; i += 2)
    if (x >= spans[i] && x < spans[i + 1]) return true;
  return false;
}
